--[=[
	An enum value used to represent the Promise's status.
	@interface ServiceLifetime
	@tag enum
	@within ServiceDescriptor
	.Singleton "Singleton" -- 指定将创建服务的单个实例
	.Scoped "Scoped" -- 指定将为每个作用域创建服务的新实例
	.Transient "Transient" -- 指定每次请求服务时都将创建一个新实例
]=]
local ServiceLifetime = {
	Singleton = "Singleton",

	Scoped = "Scoped",

	Transient = "Transient",
}

export type Type = typeof(require(ServiceLifetime))

-- 导出模块
return ServiceLifetime
